// GENERATED preamble — every unit in the estate starts here, identically.
// Rejects an envelope whose MAJOR version this unit does not implement, rather than
// half-processing a shape it does not understand.
const SUPPORTED_MAJOR = 1;
const raw = $json.envelope ?? $json;
const v = String(raw.envelope_version ?? '0.0.0');
if (Number(v.split('.')[0]) !== SUPPORTED_MAJOR) {
  throw new Error('VALIDATION_FAILED: envelope_version ' + v + ' is not supported by approve.human.request@1.0.0 (needs ' + SUPPORTED_MAJOR + '.x)');
}
for (const f of ['trace_id', 'tenant_id', 'idempotency_key']) {
  if (!raw[f]) throw new Error('VALIDATION_FAILED: envelope.' + f + ' is required');
}
if (raw.deadline_at && Date.parse(raw.deadline_at) < Date.now()) {
  // Fail fast rather than start work that cannot finish in time.
  throw new Error('TIMEOUT: deadline_at ' + raw.deadline_at + ' already passed before approve.human.request started');
}
return [{ json: {
  ...raw,
  span_id: 'spn_' + Math.random().toString(36).slice(2, 10),
  parent_span_id: raw.span_id ?? null,
  policy: raw.policy ?? {},
  budget: raw.budget ?? {},
  provenance: raw.provenance ?? [],
  _started_at: Date.now(),
  _capability: "approve.human.request",
  _capability_version: "1.0.0"
} }];

// GENERATED telemetry — span_start.
const e = $json;
return [{ json: { ...e, _telemetry: {
  event_id: 'evt_' + Math.random().toString(36).slice(2, 12),
  trace_id: e.trace_id, span_id: e.span_id, parent_span_id: e.parent_span_id,
  tenant_id: e.tenant_id, brand_id: e.brand_id ?? null, vertical: e.vertical ?? null,
  capability: "approve.human.request", capability_version: "1.0.0",
  layer: "terminal", stage: e.stage ?? null,
  event: 'span_start', at: new Date().toISOString()
} } }];

// A reviewer approves in seconds or not at all. The packet must answer: what is it, where
// is it going, what did the automated gates say, and what has it cost so far.
const e = $('Envelope In').first().json;
const p = e.payload;
const gates = p.gates || {};
const gateLine = Object.entries(gates).map(([k, v]) => `${v === 'pass' || v === 'approved' || v === 'not_required' ? 'OK' : v === 'warn' ? 'WARN' : 'FAIL'} ${k}`).join('  |  ');
return [{ json: {
  approval_id: 'apr_' + e.trace_id.slice(0, 12) + '_' + ($runIndex || 0),
  summary: `${p.channel || 'multi'} / ${p.format || ''} — ${p.title || (p.body || '').slice(0, 80)}`,
  gate_line: gateLine,
  findings: [...(p.compliance_findings || []), ...(p.brand_violations || [])].slice(0, 5),
  cost_so_far_minor_units: (e.budget?.spent_minor_units ?? 0),
  preview_urls: p.asset_urls || [],
  body_preview: (p.body || p.caption || '').slice(0, 900),
  trace_id: e.trace_id,
  expires_at: new Date(Date.now() + (p.timeout_hours || 24) * 3600e3).toISOString()
} }];

